package com.crewbeat.hondabox.tests;
import android.app.*;import android.app.job.*;import android.content.*;import android.os.*;import com.crewbeat.hondabox.*;import java.util.*;import java.util.concurrent.*;import java.util.function.BooleanSupplier;
/** Real service, broadcasts, periodic job and cross-UID FYT fixture; emulator only. */
public final class BackgroundRecoveryTests extends Instrumentation {
 private final ProbeState state=ProbeState.INSTANCE;private Context c;private int checks;
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 private void check(boolean ok,String message){checks++;if(!ok)throw new AssertionError(message);}
 private void await(BooleanSupplier predicate,String message)throws Exception{long end=SystemClock.uptimeMillis()+6000;while(!predicate.getAsBoolean()&&SystemClock.uptimeMillis()<end)SystemClock.sleep(30);check(predicate.getAsBoolean(),message);}
 private void main(Runnable task){Throwable[] failure={null};runOnMainSync(()->{try{task.run();}catch(Throwable e){failure[0]=e;}});if(failure[0]!=null)throw new AssertionError("main-thread test action",failure[0]);}
 private SharedPreferences bg(){return c.getSharedPreferences("background",0);}
 private JobInfo job(){return ((JobScheduler)c.getSystemService(Context.JOB_SCHEDULER_SERVICE)).getPendingJob(BackgroundRecovery.JOB_ID);}
 private void stopService()throws Exception{c.stopService(new Intent(c,ProbeService.class));await(()->!state.overlaySnapshot().running,"service stopped");SystemClock.sleep(250);}
 private String presetCache(){try{return state.radioPresets.json().toString();}catch(Exception e){throw new RuntimeException(e);}}
 private String shell(String command)throws Exception{try(android.os.ParcelFileDescriptor fd=getUiAutomation().executeShellCommand(command);java.io.InputStream in=new android.os.ParcelFileDescriptor.AutoCloseInputStream(fd)){java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] bytes=new byte[1024];int n;while((n=in.read(bytes))!=-1)out.write(bytes,0,n);return out.toString("UTF-8");}}
 private void connected()throws Exception{await(()->state.overlaySnapshot().running&&state.overlaySnapshot().connected&&Integer.valueOf(6291908).equals(state.overlaySnapshot().number(1000)),"read-only FYT fixture connected");}
 private String fixture(Intent i)throws Exception{CountDownLatch latch=new CountDownLatch(1);String[] result={null};i.setComponent(new ComponentName("com.syu.ms","app.ControlReceiver"));c.sendOrderedBroadcast(i,null,new BroadcastReceiver(){@Override public void onReceive(Context x,Intent y){result[0]=getResultData();latch.countDown();}},new Handler(Looper.getMainLooper()),0,null,null);check(latch.await(4,TimeUnit.SECONDS),"fixture responded");return result[0];}
 private void broadcast(String action)throws Exception{fixture(new Intent().putExtra("fytAcc",BackgroundRecovery.ACC_ON.equals(action)?1:0));}
 private void accOnManifest(){c.sendBroadcast(new Intent(BackgroundRecovery.ACC_ON).setComponent(new ComponentName(c,FytPowerReceiver.class)));}
 private void restore(SharedPreferences prefs,Map<String,?> values){SharedPreferences.Editor e=prefs.edit().clear();for(Map.Entry<String,?> item:values.entrySet()){Object v=item.getValue();String k=item.getKey();if(v instanceof Boolean)e.putBoolean(k,(Boolean)v);else if(v instanceof String)e.putString(k,(String)v);else if(v instanceof Integer)e.putInt(k,(Integer)v);else if(v instanceof Long)e.putLong(k,(Long)v);else if(v instanceof Float)e.putFloat(k,(Float)v);}e.commit();}
 @Override public void onStart(){Bundle result=new Bundle();int outcome=Activity.RESULT_OK;c=getTargetContext();SharedPreferences overlay=c.getSharedPreferences("overlay",0);if(!Build.HARDWARE.contains("ranchu")&&!Build.HARDWARE.contains("goldfish")){result.putString("failure","Emulator only; no service or preferences changed");finish(1,result);return;}Map<String,?> oldBg=new HashMap<>(bg().getAll()),oldOverlay=new HashMap<>(overlay.getAll());try{
  check(Build.HARDWARE.contains("ranchu")||Build.HARDWARE.contains("goldfish"),"disposable emulator required");
  c.getPackageManager().getServiceInfo(new ComponentName("com.syu.ms","app.ToolkitService"),0);
  BackgroundSettings.stop(c);SystemClock.sleep(400);bg().edit().clear().putBoolean("autoStart",true).putBoolean("recovery",true).putBoolean("paused",false).commit();
  SharedPreferences.Editor off=overlay.edit();for(String key:new String[]{"volume","source","track","climate","climateStrip","carMenu","unknown","audioScreens"})off.putBoolean(key,false);off.commit();
  fixture(new Intent().putExtra("resetCommands",true));fixture(new Intent().putExtra("silent",false).putExtra("profile",6291908).putExtra("source",1).putExtra("noRouteModules",false));
  main(()->BackgroundSettings.open(c));connected();check(job()!=null,"manual start registers recovery job");check(job().getIntervalMillis()>=900000&&!job().isPersisted(),"bounded periodic job does not override boot preference across reboot");check(!ProbeApplication.foreground(),"service start opens no player/UI");
  long firstSession=state.overlaySnapshot().sessionId;main(()->BackgroundRecovery.start(c,"fyt_launcher"));SystemClock.sleep(250);check(state.overlaySnapshot().sessionId==firstSession,"repeated start preserves fresh subscriptions");
  SystemClock.sleep(2200);main(()->BackgroundRecovery.start(c,"fyt_launcher"));await(()->state.overlaySnapshot().sessionId>firstSession,"repeated FYT start reconnects stale subscriptions");connected();
  stopService();check(BackgroundSettings.wanted(c),"unexpected service destruction keeps user's run request");check(shell("cmd jobscheduler run -f com.crewbeat.hondabox "+BackgroundRecovery.JOB_ID).contains("Running job"),"Android executes actual recovery JobService");connected();check("watchdog".equals(bg().getString("lastStartReason","")),"recovery start reason recorded");
  main(()->BackgroundRecovery.enabled(c,false));check(job()==null,"recovery switch cancels periodic job");stopService();check(!BackgroundRecovery.check(c),"disabled recovery never restarts service");SystemClock.sleep(200);check(!state.overlaySnapshot().running,"service stays stopped with recovery disabled");
  main(()->BackgroundRecovery.enabled(c,true));main(()->BackgroundRecovery.check(c));connected();
  fixture(new Intent().putExtra("preset1",241));broadcast(BackgroundRecovery.ACC_OFF);await(()->!BackgroundRecovery.awake(c),"runtime ACC OFF recorded");await(()->job()==null,"ACC OFF cancels recovery job");await(()->c.getSharedPreferences("radioPresets",0).getString("received","").equals(presetCache()),"ACC OFF flushes received station cache");
  stopService();check(!BackgroundRecovery.check(c),"watchdog does not restart service after ACC OFF despite screen on");accOnManifest();connected();check(job()!=null&&BackgroundRecovery.awake(c),"manifest ACC ON restores headless service and job");check("acc_on".equals(bg().getString("lastStartReason","")),"ACC start reason recorded");
  SystemClock.sleep(2200);long beforeAcc=state.overlaySnapshot().sessionId;broadcast(BackgroundRecovery.ACC_OFF);await(()->!BackgroundRecovery.awake(c),"second runtime ACC OFF");broadcast(BackgroundRecovery.ACC_ON);await(()->BackgroundRecovery.awake(c),"runtime ACC ON recorded");await(()->state.overlaySnapshot().sessionId>beforeAcc,"ACC wake reconnects stale service");connected();
  main(()->BackgroundSettings.stop(c));await(()->!state.overlaySnapshot().running,"manual STOP finishes service");SystemClock.sleep(250);check(job()==null,"manual STOP cancels periodic job");for(String reason:new String[]{"boot","acc_on","watchdog"})main(()->{Intent stale=new Intent(c,ProbeService.class).putExtra(BackgroundRecovery.REASON,reason).putExtra("backgroundStart",true);if(Build.VERSION.SDK_INT>=26)c.startForegroundService(stale);else c.startService(stale);});SystemClock.sleep(32000);check(!state.overlaySnapshot().running&&BackgroundSettings.paused(c),"queued automatic foreground starts after STOP are rejected without timeout/crash");check(((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).getActiveNotifications().length==0,"rejected starts leave no service notification");check(!BackgroundRecovery.check(c),"watchdog respects manual pause");accOnManifest();main(()->new BootReceiver().onReceive(c,new Intent(Intent.ACTION_BOOT_COMPLETED)));main(()->new BootReceiver().onReceive(c,new Intent(Intent.ACTION_MY_PACKAGE_REPLACED)));SystemClock.sleep(350);check(!state.overlaySnapshot().running&&BackgroundSettings.paused(c),"ACC/boot/update cannot undo manual pause");
  main(()->c.startActivity(new Intent(c,BackgroundStartActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)));SystemClock.sleep(600);check(!state.overlaySnapshot().running&&BackgroundSettings.paused(c),"FYT headless launcher also respects pause");check(!ProbeApplication.foreground(),"headless launch leaves no UI");
  main(()->BackgroundSettings.open(c));connected();check(!BackgroundSettings.paused(c)&&job()!=null,"explicit UI start resumes operation and recovery");
  main(()->BackgroundSettings.autoStart(c,false));stopService();main(()->new BootReceiver().onReceive(c,new Intent(Intent.ACTION_BOOT_COMPLETED)));accOnManifest();SystemClock.sleep(350);check(!state.overlaySnapshot().running,"disabled autostart blocks boot and manifest ACC starts");
  main(()->BackgroundSettings.open(c));connected();check(state.overlaySnapshot().running,"manual start remains available with boot autostart off");
  check("[]".equals(fixture(new Intent().putExtra("getCommands",true))),"all recovery paths send zero source/transport/CAN commands");result.putString("result","PASS: "+checks+" service recovery integration checks; boot/ACC, repeat launch, periodic recovery, sleep, pause and zero vehicle commands");
 }catch(Throwable e){outcome=1;result.putString("failure",android.util.Log.getStackTraceString(e));}finally{BackgroundSettings.stop(c);SystemClock.sleep(350);restore(overlay,oldOverlay);restore(bg(),oldBg);((JobScheduler)c.getSystemService(Context.JOB_SCHEDULER_SERVICE)).cancel(BackgroundRecovery.JOB_ID);state.newSession();state.running(false);}finish(outcome,result);}
}
